#!/usr/bin/env node
/**
 * Canonical Alpha Coach API Bundler
 * Automatically generates production-ready api/app.bundle.js from backend/src/app.ts
 * Embeds Git commit SHA, version, build timestamp, and validates bundle integrity.
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const rootDir = path.resolve(__dirname, '..');
const apiDir = path.join(rootDir, 'api');
const frontendApiDir = path.join(rootDir, 'frontend', 'api');

// 1. Resolve Git Commit SHA and Build Metadata
let gitCommit = process.env.VERCEL_GIT_COMMIT_SHA || process.env.GITHUB_SHA || '';
if (!gitCommit) {
  try {
    gitCommit = execSync('git rev-parse HEAD', { cwd: rootDir, encoding: 'utf-8' }).trim();
  } catch {
    gitCommit = 'dev-' + Date.now().toString(16);
  }
}

const buildVersion = '1.0.5';
const buildTimestamp = new Date().toISOString();

const manifest = {
  buildVersion,
  gitCommit,
  buildTimestamp,
  backendSource: 'backend/src',
  target: 'node18',
  generatedBy: 'scripts/build-api-bundle.js'
};

console.log('====================================================');
console.log('  ALPHA COACH — API PRODUCTION BUNDLER');
console.log('====================================================');
console.log(`  Version:         ${buildVersion}`);
console.log(`  Commit SHA:      ${gitCommit}`);
console.log(`  Build Timestamp: ${buildTimestamp}`);
console.log('====================================================');

// 2. Resolve esbuild
let esbuild;
try {
  esbuild = require('esbuild');
} catch {
  try {
    esbuild = require(path.join(rootDir, 'frontend', 'node_modules', 'esbuild'));
  } catch (err) {
    console.error('[BUILD FATAL] Failed to locate esbuild compiler:', err.message);
    process.exit(1);
  }
}

// 3. Ensure target directories exist
[apiDir, frontendApiDir].forEach(dir => {
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
});

// 4. Update backend/src/buildInfo.ts before bundling
const buildInfoContent = `/**
 * Build and source provenance identity for Alpha Coach API
 * Automatically generated by scripts/build-api-bundle.js
 */
export interface BuildInfo {
  version: string;
  gitCommit: string;
  buildTimestamp: string;
  environment: string;
  sourceOrigin: string;
}

export const BUILD_INFO: BuildInfo = {
  version: ${JSON.stringify(buildVersion)},
  gitCommit: ${JSON.stringify(gitCommit)},
  buildTimestamp: ${JSON.stringify(buildTimestamp)},
  environment: process.env.NODE_ENV || 'production',
  sourceOrigin: 'backend/src'
};
`;

fs.writeFileSync(path.join(rootDir, 'backend', 'src', 'buildInfo.ts'), buildInfoContent, 'utf-8');

// 5. Execute esbuild Bundle
const entryFile = path.join(rootDir, 'backend', 'src', 'app.ts');
const targetBundleFile = path.join(apiDir, 'app.bundle.js');
const targetFrontendBundleFile = path.join(frontendApiDir, 'app.bundle.js');

try {
  const result = esbuild.buildSync({
    entryPoints: [entryFile],
    bundle: true,
    platform: 'node',
    target: 'node18',
    format: 'cjs',
    outfile: targetBundleFile,
    sourcemap: false,
    minify: false,
    external: [
      'pg',
      'pg-native',
      'sql.js',
      'bufferutil',
      'utf-8-validate'
    ],
    define: {
      'process.env.GIT_COMMIT_SHA': JSON.stringify(gitCommit),
      'process.env.BUILD_VERSION': JSON.stringify(buildVersion),
      'process.env.BUILD_TIMESTAMP': JSON.stringify(buildTimestamp)
    }
  });

  if (result.errors && result.errors.length > 0) {
    console.error('[BUILD ERROR] esbuild failed with errors:', result.errors);
    process.exit(1);
  }

  // Copy bundle to frontend/api for unified monorepo support
  fs.copyFileSync(targetBundleFile, targetFrontendBundleFile);

  // Write build manifests
  const manifestJson = JSON.stringify(manifest, null, 2);
  fs.writeFileSync(path.join(apiDir, 'build-manifest.json'), manifestJson, 'utf-8');
  fs.writeFileSync(path.join(frontendApiDir, 'build-manifest.json'), manifestJson, 'utf-8');

  // Verify bundle output
  const stat = fs.statSync(targetBundleFile);
  if (stat.size < 1000) {
    console.error('[BUILD FATAL] Generated bundle is suspiciously small:', stat.size, 'bytes');
    process.exit(1);
  }

  console.log(`[SUCCESS] Generated ${targetBundleFile} (${(stat.size / 1024).toFixed(1)} KB)`);
  console.log(`[SUCCESS] Synchronized ${targetFrontendBundleFile}`);
  console.log(`[SUCCESS] Created build-manifest.json`);
  console.log('====================================================\n');
} catch (err) {
  console.error('[BUILD FATAL] Exception during bundle generation:', err);
  process.exit(1);
}
